// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, address target, bytes memory data) public {
        vm.assume(value > 0);
        vm.deal(address(c), value);
        bool ok;
        try c.sendMoney(target, value, data) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
